<?php $titulo='Agenda de políticas'; $modulo='agenda'; $dias=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb']; ?>
<div class="d-flex justify-content-between align-items-center mb-3"><div><h4 class="mb-1">Agenda semanal</h4><p class="text-muted mb-0">Visualização das regras ativas cadastradas no Squid.</p></div><a class="btn btn-outline-primary" href="/agenda/simulador"><i class="bi bi-bezier2"></i> Simular política</a></div><div class="card"><div class="table-responsive"><table class="table table-bordered align-middle mb-0"><thead class="table-light"><tr><th>Regra / grupo</th><?php foreach($dias as $d):?><th class="text-center"><?=$d?></th><?php endforeach;?></tr></thead><tbody><?php foreach($horarios as $r):?><tr><td><strong><?=h($r['nome'])?></strong><div class="small text-muted"><?=h($r['grupo_nome']??'Todos os grupos')?> · <?=h(substr($r['hora_inicio'],0,5))?>–<?=h(substr($r['hora_fim'],0,5))?></div></td><?php for($i=0;$i<7;$i++):?><td class="text-center"><?php if(($r['dias_semana'][$i]??'0')==='1'):?><span class="badge bg-<?=$r['acao']==='permitir'?'success':'danger'?>"><?=h(ucfirst($r['acao']))?></span><?php else:?><span class="text-muted">—</span><?php endif;?></td><?php endfor;?></tr><?php endforeach;?><?php if(!$horarios):?><tr><td colspan="8" class="text-center text-muted py-4">Nenhuma regra semanal ativa cadastrada.</td></tr><?php endif;?></tbody></table></div></div>
